package io.rift.cronos;

import android.content.*;import android.database.DatabaseErrorHandler;import android.database.sqlite.SQLiteDatabase;
import androidx.test.ext.junit.runners.AndroidJUnit4;import androidx.test.platform.app.InstrumentationRegistry;
import org.junit.*;import org.junit.runner.RunWith;import org.json.*;import java.io.File;import java.util.*;import java.util.concurrent.*;
import static org.junit.Assert.*;

/** Run on a disposable emulator/device: ./gradlew connectedDebugAndroidTest.
 * Uses a unique prefixed database, never the user's actual workspace. No network or wallet calls. */
@RunWith(AndroidJUnit4.class)
public final class WorkspaceInstrumentedTest {
 private Context target,isolated;private LocalWorkspace store;private ReceiptWatchStore watches;private String prefix;
 @Before public void before(){target=InstrumentationRegistry.getInstrumentation().getTargetContext();prefix="test-"+UUID.randomUUID()+"-";
  isolated=new ContextWrapper(target){
   @Override public File getDatabasePath(String name){return target.getDatabasePath(prefix+name);}
   @Override public SQLiteDatabase openOrCreateDatabase(String name,int mode,SQLiteDatabase.CursorFactory factory){return target.openOrCreateDatabase(prefix+name,mode,factory);}
   @Override public SQLiteDatabase openOrCreateDatabase(String name,int mode,SQLiteDatabase.CursorFactory factory,DatabaseErrorHandler handler){return target.openOrCreateDatabase(prefix+name,mode,factory,handler);}
   @Override public boolean deleteDatabase(String name){return target.deleteDatabase(prefix+name);}
  };store=new LocalWorkspace(isolated);watches=new ReceiptWatchStore(isolated);
 }
 @After public void after(){if(store!=null)store.close();if(watches!=null)watches.close();target.deleteDatabase(prefix+"rift-personal.sqlite");target.deleteDatabase(prefix+"rift-receipt-watches.sqlite");}
 private JSONObject draft()throws Exception{return new JSONObject().put("mode",0).put("config",new JSONObject().put("name","Original artwork"));}
 @Test public void saveRestoreAndProfileIsolation()throws Exception{String a="25:device",b="25:0x"+"aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa";String id=store.save(a,"Native draft",draft());assertEquals(1,store.drafts(a).length());assertEquals(0,store.drafts(b).length());store.delete(b,id);assertEquals(1,store.drafts(a).length());JSONObject backup=store.backup(a);assertEquals(1,store.restore(a,backup));assertEquals(2,store.drafts(a).length());store.delete(a,id);assertEquals(1,store.drafts(a).length());}
 @Test public void failedImportRollsBackDraftsAndFavorites()throws Exception{String a="25:device";for(int i=0;i<49;i++)store.save(a,"Draft "+i,draft());JSONObject value=store.backup(a);value.put("drafts",new JSONArray().put(new JSONObject().put("title","one").put("document",draft())).put(new JSONObject().put("title","two").put("document",draft())));value.put("favorites",new JSONArray().put("0x"+"bbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbb"));try{store.restore(a,value);fail("overflow accepted");}catch(IllegalStateException expected){}assertEquals(49,store.drafts(a).length());assertEquals(0,store.favorites(a).length());}
 @Test public void rejectsCredentialFieldsBeforeWriting()throws Exception{try{store.save("25:device","Bad",new JSONObject().put("config",new JSONObject().put("api_key","never")));fail("secret accepted");}catch(IllegalArgumentException expected){}assertEquals(0,store.drafts("25:device").length());}
 @Test public void concurrentConnectionsPreserveDraftLimit()throws Exception{LocalWorkspace second=new LocalWorkspace(isolated);ExecutorService pool=Executors.newFixedThreadPool(2);try{for(int i=0;i<49;i++)store.save("25:device","Draft "+i,draft());Callable<Boolean> first=()->{try{store.save("25:device","First",draft());return true;}catch(IllegalStateException e){return false;}};Callable<Boolean> other=()->{try{second.save("25:device","Second",draft());return true;}catch(IllegalStateException e){return false;}};List<Future<Boolean>> result=pool.invokeAll(Arrays.asList(first,other));assertNotEquals(result.get(0).get(),result.get(1).get());assertEquals(50,store.drafts("25:device").length());}finally{pool.shutdownNow();second.close();}}
 @Test public void favoritesDeduplicateAcrossBackupImports()throws Exception{String a="25:device",address="0x"+"bbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbb";store.favorite(a,address,true);store.favorite(a,address,true);assertEquals(1,store.favorites(a).length());store.restore(a,store.backup(a));assertEquals(1,store.favorites(a).length());}
 @Test public void staleWatchClaimCannotOverwriteRestartOrRemoval()throws Exception{String a="25:device",h="0xaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa";watches.watch(a,h,1000);JSONObject old=watches.claim(1000);watches.watch(a,h,1001);assertFalse(watches.complete(old,new JSONObject(),"watching","old",1002,false));JSONObject current=watches.claim(1002);watches.remove(a,h);assertFalse(watches.complete(current,new JSONObject(),"observed-inclusion","old",1003,false));assertEquals(0,watches.list(a).length());}
 @Test public void receiptWatchCountAndExpiryAreBounded()throws Exception{String a="25:device";for(int i=0;i<20;i++)watches.watch(a,"0x"+String.format(java.util.Locale.ROOT,"%064x",i),1000);try{watches.watch(a,"0x"+String.format(java.util.Locale.ROOT,"%064x",21),1000);fail("watch overflow accepted");}catch(IllegalStateException expected){}assertEquals(20,watches.active());watches.expire(1000+WatchPolicy.MAX_AGE);assertEquals(0,watches.active());assertEquals("expired",watches.list(a).getJSONObject(0).getString("status"));}
 @Test public void receiptCheckpointDefersDuplicateClaimAndStopsAtInclusion()throws Exception{String a="25:device",h="0xbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbb";watches.watch(a,h,1000);JSONObject first=watches.claim(1000);assertEquals(1,first.getInt("attempts"));assertNull(watches.claim(1000));assertTrue(watches.complete(first,new JSONObject().put("state","not-found-or-pending"),"watching","pending",1000,false));JSONObject second=watches.claim(1000+WatchPolicy.INTERVAL);assertEquals(2,second.getInt("attempts"));assertTrue(watches.complete(second,new JSONObject().put("state","included-success"),"observed-inclusion","Not finality",1000+WatchPolicy.INTERVAL,false));assertEquals(0,watches.active());assertEquals("observed-inclusion",watches.list(a).getJSONObject(0).getString("status"));assertFalse(watches.list(a).getJSONObject(0).has("claim"));}

 @Test public void receiptClaimSurvivesConnectionReopenAndPreservesLease()throws Exception{String a="25:device",h="0x"+String.format(java.util.Locale.ROOT,"%064x",77);watches.watch(a,h,1000);JSONObject claimed=watches.claim(1000);watches.close();watches=new ReceiptWatchStore(isolated);assertNull(watches.claim(1001));JSONObject next=watches.claim(1000+WatchPolicy.INTERVAL);assertEquals(2,next.getInt("attempts"));assertFalse(watches.complete(claimed,new JSONObject(),"observed-inclusion","stale",1000+WatchPolicy.INTERVAL,false));assertTrue(watches.complete(next,new JSONObject(),"watching","recovered",1000+WatchPolicy.INTERVAL,false));}
 @Test public void receiptWatchClockRollbackExpiresAndProfileClearIsIsolated()throws Exception{String a="25:device",b="25:0xaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa",h="0x"+String.format(java.util.Locale.ROOT,"%064x",78);watches.watch(a,h,1000);watches.watch(b,h,1000);watches.expire(999);assertEquals(0,watches.active());assertEquals("expired",watches.list(a).getJSONObject(0).getString("status"));watches.clear(a);assertEquals(0,watches.list(a).length());assertEquals(1,watches.list(b).length());}

 @Test public void rasterPreviewReencodesAndBoundsOutput()throws Exception{android.graphics.Bitmap b=android.graphics.Bitmap.createBitmap(600,300,android.graphics.Bitmap.Config.ARGB_8888);java.io.ByteArrayOutputStream bytes=new java.io.ByteArrayOutputStream();try{b.eraseColor(android.graphics.Color.GREEN);assertTrue(b.compress(android.graphics.Bitmap.CompressFormat.PNG,100,bytes));}finally{b.recycle();}JSONObject preview=RasterPreview.decode(bytes.toByteArray(),"image/png");assertTrue(preview.getInt("width")<=256);assertTrue(preview.getInt("height")<=256);assertEquals(600,preview.getInt("originalWidth"));assertTrue(preview.getString("dataUri").startsWith("data:image/png;base64,"));assertTrue(preview.getInt("outputBytes")<=65536);}
 @Test public void rasterPreviewRejectsSpoofedMimeAndExcessiveDimensions()throws Exception{try{RasterPreview.decode("<svg onload='bad'/>".getBytes(java.nio.charset.StandardCharsets.UTF_8),"image/png");fail("SVG accepted");}catch(java.io.IOException expected){}android.graphics.Bitmap b=android.graphics.Bitmap.createBitmap(2049,1,android.graphics.Bitmap.Config.ARGB_8888);java.io.ByteArrayOutputStream out=new java.io.ByteArrayOutputStream();try{b.compress(android.graphics.Bitmap.CompressFormat.PNG,100,out);}finally{b.recycle();}try{RasterPreview.decode(out.toByteArray(),"image/png");fail("Oversize dimensions accepted");}catch(java.io.IOException expected){}}

}
